import { Component } from '@angular/core';
import { WeaponTypeForm } from '../../model/weaponType-form';
import { WeaponTypeService } from '../../service/weaponType.service';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'app-weapon-type-edit',
  templateUrl: './weapon-type-edit.component.html',
  styleUrls: ['./weapon-type-edit.component.css']
})
export class WeaponTypeEditComponent implements OnInit {
  uuid: string | undefined;
  weaponType: WeaponTypeForm | undefined;
  original: WeaponTypeForm | undefined;
  weaponTypes: WeaponTypeForm | undefined;

  constructor(
    private weaponTypeService: WeaponTypeService,
    private route: ActivatedRoute,
    private router: Router
  ) {
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.weaponTypeService.getWeaponTypes()
        .subscribe(weaponTypes => this.weaponTypes = weaponTypes);

      this.weaponService.getWeapon(params['uuid'])
        .subscribe(weapon => {
          this.uuid = weapon.id;
          this.weapon = {
            name: weapon.name,
            description: weapon.description,
            damage: weapon.damage,
            range: weapon.range,
            weaponTypeId: weapon.weaponTypeId
          };
          this.original = {...this.weapon};
        });
    });
  }

  onSubmit(): void {
    this.weaponService.putWeapon(this.uuid!, this.weapon!)
      .subscribe(() => this.router.navigate(['/weapons']));
  }
}
